using System.IO;
using System.Linq;
using Ironfront.Audio;
using Ironfront.Core.Audio;
using UnityEditor;
using UnityEngine;

namespace Ironfront.EditorTools.Art
{
    /// <summary>
    /// Synthesises every Ironfront sound with <see cref="SfxSynth"/>, writes them as WAV files under
    /// Assets/Ironfront/Audio and builds the <see cref="SoundBank"/> (ids, variants, categories, volumes and
    /// voice limits). All audio is generated by this project's own code: no samples, libraries or services.
    /// Menu: Ironfront > Art > Generate Audio.
    /// </summary>
    public static class AudioContentBuilder
    {
        public const string AudioDir = "Assets/Ironfront/Audio";
        public const string BankPath = AudioDir + "/SoundBank.asset";

        [MenuItem("Ironfront/Art/Generate Audio")]
        public static void GenerateFromMenu() => Debug.Log("[Ironfront] " + Generate());

        public static string Generate()
        {
            RtsSandboxBuilder.EnsureFolder(AudioDir);
            int written = 0;
            foreach (var name in SfxSynth.Recipes)
            {
                string path = $"{AudioDir}/{name}.wav";
                File.WriteAllBytes(path, SfxSynth.ToWav(SfxSynth.Generate(name)));
                AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
                var importer = (AudioImporter)AssetImporter.GetAtPath(path);
                var settings = importer.defaultSampleSettings;
                bool loop = SfxSynth.IsLoop(name);
                settings.loadType = loop ? AudioClipLoadType.CompressedInMemory : AudioClipLoadType.DecompressOnLoad;
                settings.compressionFormat = loop ? AudioCompressionFormat.Vorbis : AudioCompressionFormat.ADPCM;
                settings.quality = 0.7f;
                importer.defaultSampleSettings = settings;
                importer.forceToMono = true;
                importer.loadInBackground = false;
                importer.SaveAndReimport();
                written++;
            }

            var bank = AssetDatabase.LoadAssetAtPath<SoundBank>(BankPath);
            if (bank == null)
            {
                bank = ScriptableObject.CreateInstance<SoundBank>();
                AssetDatabase.CreateAsset(bank, BankPath);
            }
            var so = new SerializedObject(bank);
            var entries = so.FindProperty("entries");
            var specs = new (SoundId id, string prefix, SoundCategory cat, float volume, float jitter, int voices, float interval, bool positional)[]
            {
                (SoundId.SelectAck, "ack_select", SoundCategory.Voice, 0.55f, 0.02f, 1, 0.25f, false),
                (SoundId.MoveAck, "ack_move", SoundCategory.Voice, 0.55f, 0.02f, 1, 0.2f, false),
                (SoundId.AttackAck, "ack_attack", SoundCategory.Voice, 0.6f, 0.02f, 1, 0.2f, false),
                (SoundId.LightCannon, "light_cannon", SoundCategory.Effects, 0.5f, 0.08f, 6, 0.03f, true),
                (SoundId.HeavyCannon, "heavy_cannon", SoundCategory.Effects, 0.65f, 0.06f, 5, 0.05f, true),
                (SoundId.Impact, "impact", SoundCategory.Effects, 0.3f, 0.1f, 6, 0.03f, true),
                (SoundId.ExplosionSmall, "explosion_small", SoundCategory.Effects, 0.75f, 0.08f, 4, 0.08f, true),
                (SoundId.ExplosionLarge, "explosion_large", SoundCategory.Effects, 0.85f, 0.05f, 3, 0.12f, true),
                (SoundId.StructureDestroyed, "structure_destroyed", SoundCategory.Effects, 1f, 0.03f, 2, 0.3f, true),
                (SoundId.PlaceStructure, "place_structure", SoundCategory.Effects, 0.7f, 0.03f, 2, 0.1f, true),
                (SoundId.ConstructionComplete, "construction_complete", SoundCategory.Interface, 0.5f, 0f, 1, 0.3f, false),
                (SoundId.UnitReady, "unit_ready", SoundCategory.Interface, 0.45f, 0f, 1, 0.4f, false),
                (SoundId.Delivery, "delivery", SoundCategory.Effects, 0.4f, 0.04f, 2, 0.3f, true),
                (SoundId.UiClick, "ui_click", SoundCategory.Interface, 0.45f, 0.03f, 2, 0.03f, false),
                (SoundId.UiHover, "ui_hover", SoundCategory.Interface, 0.25f, 0.03f, 1, 0.05f, false),
                (SoundId.UiError, "ui_error", SoundCategory.Interface, 0.45f, 0f, 1, 0.25f, false),
                (SoundId.Alert, "alert", SoundCategory.Interface, 0.45f, 0f, 1, 4f, false),
                (SoundId.Victory, "victory", SoundCategory.Interface, 0.7f, 0f, 1, 1f, false),
                (SoundId.Defeat, "defeat", SoundCategory.Interface, 0.7f, 0f, 1, 1f, false),
                (SoundId.MachineGun, "machine_gun", SoundCategory.Effects, 0.35f, 0.08f, 5, 0.05f, true),
                (SoundId.RocketLaunch, "rocket_launch", SoundCategory.Effects, 0.6f, 0.06f, 4, 0.08f, true),
                (SoundId.ResearchComplete, "research_complete", SoundCategory.Interface, 0.55f, 0f, 1, 1f, false),
            };
            entries.arraySize = specs.Length;
            for (int i = 0; i < specs.Length; i++)
            {
                var (id, prefix, cat, volume, jitter, voices, interval, positional) = specs[i];
                var e = entries.GetArrayElementAtIndex(i);
                e.FindPropertyRelative("id").enumValueIndex = (int)id;
                var clips = SfxSynth.Recipes.Where(r => r == prefix || r.StartsWith(prefix + "_")).Select(Clip).ToArray();
                var list = e.FindPropertyRelative("clips");
                list.arraySize = clips.Length;
                for (int c = 0; c < clips.Length; c++) list.GetArrayElementAtIndex(c).objectReferenceValue = clips[c];
                e.FindPropertyRelative("category").enumValueIndex = (int)cat;
                e.FindPropertyRelative("volume").floatValue = volume;
                e.FindPropertyRelative("pitchJitter").floatValue = jitter;
                e.FindPropertyRelative("maxVoices").intValue = voices;
                e.FindPropertyRelative("minInterval").floatValue = interval;
                e.FindPropertyRelative("positional").boolValue = positional;
            }
            so.FindProperty("ambienceLoop").objectReferenceValue = Clip("ambience_wind_loop");
            so.FindProperty("engineLoop").objectReferenceValue = Clip("engine_loop");
            var battle = so.FindProperty("distantBattle");
            var rumbles = SfxSynth.Recipes.Where(r => r.StartsWith("distant_battle")).Select(Clip).ToArray();
            battle.arraySize = rumbles.Length;
            for (int i = 0; i < rumbles.Length; i++) battle.GetArrayElementAtIndex(i).objectReferenceValue = rumbles[i];
            so.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(bank);
            AssetDatabase.SaveAssets();
            return $"Audio: {written} clips synthesised, {specs.Length} sound ids in {BankPath}";
        }

        private static AudioClip Clip(string name) => AssetDatabase.LoadAssetAtPath<AudioClip>($"{AudioDir}/{name}.wav");

        public static SoundBank LoadBank() => AssetDatabase.LoadAssetAtPath<SoundBank>(BankPath);
    }
}
